INSERT INTO `repair_data` (`id`, `repair_reason`, `failure_reason`, `admission_date`, `release_date`, `actions_description`, `repair_creator`, `creator_id`, `created_at`, `serial_number`, `case_number`) VALUES
(1, 'В ходе испытаний мокрого индуктора произошёл выход из строя 4-ого передатчика', 'Сгорел выходной мост индуктора', '2025-04-15', '2025-06-02', 'Замена платы 4-ого передатчика. Настройка метрологии. Поверка на кольцах, прогрев. ', ' Администратор ', 7, '2025-06-02 22:14:25', '109', '008-2024'),
(2, 'Отказал на скважине при попытке считать данные. Были сохранены данные предыдущей скважины.', 'Короткое замыкание по цепи батареи.', '2025-05-10', '2025-06-02', 'Ремонт транзитной платы №2, замена верхних экранов передающих индукторов, прогрев кольца.', ' Администратор ', 7, '2025-06-02 22:40:39', '108', '005-2024'),
(3, 'не могли вычитать данные на скважине. ', 'На транзитной плате вышел из строя керамический конденсатор на линии питания', '2025-05-12', '2025-06-05', 'произведён ремонт транзитной платы', 'Литвинов Владислав Глебович', 26, '2025-06-05 15:46:20', '108', '005-2024'),
(4, 'В скважине Т3_400 фаза намного смещена на 5-6 градусов относительно ожидаемой величины.\r\nТ4_2000 нарушен порядок. Кольца проходит успешно.', '', '2025-06-05', '2025-07-10', ' Заменены провода индукторов передатчиков.\r\n Экранирование провода с змеиной оплётки переделано на трубки на всех индукторах.\r\n Экраны индукторов заменены с тонких текстолитовых на полиамидные, подключение экранов к земле реализовано при помощи медных полос отожжённых в середине с предварительным лужением хвостов.\r\n Прописан новый воздух', 'Литвинов Владислав Глебович', 26, '2025-06-05 16:25:55', '106', '003-2023'),
(10, 'Перепрошивка на новые частоты (399, 1960) калибровка.', 'Обнаружена неисправность аварийного разъема.', '2025-06-05', '2025-06-06', '', 'Литвинов Владислав Глебович', 26, '2025-06-09 07:34:48', '105', '002-2023'),
(13, 'Показания не соответствовали ожидаемым характеристикам. отсутствует повторяемость показаний спуск-подъем. Предполагаемая причина направленная характеристика приборов', '', '2025-10-06', '2025-11-02', 'Перемотка приёмных индукторов (2х5 витков эмальпровода 0,2 мм);\r\n экранирование запитки приёмных индуктрров медными и ферритовыми трубками; \r\nустановка синфазных дросселей и Y-конденсаторов 2х10 мкФ в линиях 6 В и 24 В на входе транзитной платы Т4.', 'Литвинов Владислав Глебович', 26, '2025-11-06 15:13:22', '414', '036-2020'),
(14, 'Показания не соответствовали ожидаемым характеристикам. отсутствует повторяемость показаний спуск-подъем. Предполагаемая причина направленная характеристика приборов', '', '2025-10-06', '2025-11-02', 'Перемотка приёмных индукторов (2х5 витков эмальпровода 0,2 мм);\r\n экранирование запитки приёмных индуктрров медными и ферритовыми трубками; \r\nустановка синфазных дросселей и Y-конденсаторов 2х10 мкФ в линиях 6 В и 24 В на входе транзитной платы Т4.', 'Литвинов Владислав Глебович', 26, '2025-11-06 15:14:23', '415', '041-2022'),
(15, 'Показания не соответствовали ожидаемым характеристикам. отсутствует повторяемость показаний спуск-подъем. Предполагаемая причина направленная характеристика приборов', '', '2025-10-06', '2025-11-02', 'Перемотка приёмных индукторов (2х5 витков эмальпровода 0,2 мм);\r\n экранирование запитки приёмных индуктрров медными и ферритовыми трубками; \r\nустановка синфазных дросселей и Y-конденсаторов 2х10 мкФ в линиях 6 В и 24 В на входе транзитной платы Т4.', 'Литвинов Владислав Глебович', 26, '2025-11-06 15:15:04', '416', '045-2022'),
(16, 'не читался с аварийного разъёма', 'не качественный контакт в аварийном разъёме', '2025-10-06', '2025-11-02', 'почищен разъём, проверено качество связи в обход оного, иных неисправностей не обнаружено.', 'Литвинов Владислав Глебович', 26, '2025-11-10 08:33:31', '199', '003-2022'),
(17, 'Отказ в скважине.', 'Замыкание по линии +-16В', '2025-10-21', '2025-10-31', 'Ремонт проведен в Октябрьском. Перебило оба провода под передатчиком №1. Разобрали Т1, заменили все провода, проходящие\r\nЧерез Т-1, немного расширили пазы возле индуктора. Всё восстановили, залили компаундом. \r\nСобрали зонд, прописали воздух в цеху и КИС. От кипа без замечаний', 'Набиуллин Ильнар Габдуллович', 24, '2025-11-21 03:34:17', '105', '002-2023'),
(18, '---', '---', '2025-09-01', '2026-01-19', 'Комплекс действий по замене плат и индукторов.', 'Литвинов Владислав Глебович', 26, '2025-12-24 08:14:14', '108', '005-2024'),
(19, 'Отказ передатчика №3', 'Проблема в плате передатчика', '2026-01-19', '2026-01-19', 'Попросили отправить в Воронеж для полной переделки', 'Набиуллин Ильнар Габдуллович', 24, '2026-01-19 11:28:19', '106', '003-2023'),
(20, 'Отказ ИК в открытом стволе, 30 м из 990м. Акселерометры работали', 'Вероятная причина в шине Enable, т.к. произошло обнуление фрейма.', '2026-01-19', '2026-01-23', 'Причина была в модуле БП. Упало напряжение.', 'Набиуллин Ильнар Габдуллович', 24, '2026-01-19 11:33:49', '107', '004-2023'),
(21, 'Отказ третьего передатчика. Рекламация КИП на точность измерений.', 'выработка ресурса текущей конструкции.', '2026-01-24', '2026-02-06', 'Полная переборка. Замена плат, проводниковых линий, переделка индукторов.', 'Литвинов Владислав Глебович', 26, '2026-01-30 07:45:26', '106', '003-2023'),
(22, 'Короткое замыкание по +-16В', 'КЗ в керамическом конденсаторе С7 10мкф на транзитной плате передатчика Т2.', '2026-02-16', '2026-02-17', 'Замена конденсатора. Тестовая запись. Потребление в норме.', 'Набиуллин Ильнар Габдуллович', 24, '2026-02-17 06:04:25', '105', '002-2023'),
(23, 'Отписал 9 часов и начал писать нули, затем работа восстановилась. Акселерометры писали весь интервал.', 'Найдены 2 проблемы в плате MCU. Питание +5В нестабильно скачет от 3,6 до 4,2В. Про прогреве платы феном до 60гр 3.3В падает до 2.5В. Обнаружил замыкание танталового конденсатора С5 22*16В.', '2026-03-17', '2026-03-19', 'Пропайка микросхемы DC-DC канала 5В, напряжение стало стабильным 4,78В. Замена танталового конденсатора С5. Прогрев платы до 90гр, всё нормально. По просьбе Петра выпаял резисторы R905 3.3к на всех каналах.', 'Набиуллин Ильнар Габдуллович', 24, '2026-03-19 03:47:54', '106', '003-2023'),
(24, 'Нет связи с прибором, не смогли считать материал', 'Вышел из строя клапан SN74LVC1T45 на линии 1W и резистор 51Ом на плате управления', '2026-03-30', '2026-04-01', 'Замена микросхемы и резистора. Залита новая прошивка на плату управления и на ЦК с бутлодером.', 'Набиуллин Ильнар Габдуллович', 24, '2026-04-01 04:24:14', '107', '004-2023'),
(25, 'Вывод картографа этого типа из эксплуатации.', '', '2026-02-24', '2026-04-09', 'Произведена полная переборка прибора. Установка плат нового типа. укладка коммуникаций с применением латунных трубок большого диаметра и медных трубок малого диаметра для экранирования линий DDS, а так же линий соединяющих транзитные платы с разъемами. Индукторы переделаны из ленточных в проводные без изменения текапиковых вставок, передатчики содержат 4 витка проводом сечением 0,5. приёмники выполнены одним витком экранированного провода.', 'Литвинов Владислав Глебович', 26, '2026-04-08 07:30:28', '102', '003-2022'),
(26, 'Короткое замыкание по линии +-16В', 'КЗ в керамическом конденсаторе С14 на транзитной плате передатчика Т2.', '2026-04-13', '2026-04-16', 'Замена всех керамических конденсаторов 10мк*50В на всех транзитных платах, в том числе и на плате Олега. Обновление ПО платы Олега и ЦК под бутлоадер.', 'Набиуллин Ильнар Габдуллович', 24, '2026-04-16 04:40:42', '105', '002-2023'),
(27, 'Перепрошить ЦК под бутлоадер', '-', '2026-05-29', '2026-06-02', 'Обновление ПО  ЦК Воронеж под бутлоадер, плата Олега была обновлена дистанционно. Был обнаружен непропай 2 ноги SOT-23-3 на плате передатчика Т2, пропаял. Тестовая запись отправлена в группу, прописаны автоматически нули + КИС', 'Набиуллин Ильнар Габдуллович', 24, '2026-06-03 06:13:27', '106', '003-2023');

