INSERT INTO `repair_data_history` (`history_id`, `repair_data_id`, `repair_reason`, `failure_reason`, `admission_date`, `release_date`, `actions_description`, `changed_by_user_id`, `changed_at`) VALUES
(3, 10, 'Перепрошивка на новые частоты (399, 1960) калибровка. Обнаружена неисправность аварийного разъема.', '', '2025-06-05', '0000-00-00', 'проведен ремонт передатчика', 7, '2025-06-09 16:30:26'),
(4, 10, 'Перепрошивка на новые частоты (399, 1960) калибровка.', 'Обнаружена неисправность аварийного разъема.', '2025-06-05', NULL, '', 26, '2025-06-10 07:35:36'),
(5, 10, 'Перепрошивка на новые частоты (399, 1960) калибровка.', 'Обнаружена неисправность аварийного разъема.', '2025-06-05', NULL, '', 26, '2025-06-10 07:47:24'),
(6, 4, 'В скважине Т3_400 фаза намного смещена на 5-6 градусов относительно ожидаемой величины.\r\nТ4_2000 нарушен порядок. Кольца проходит успешно.', '', '2025-06-05', '0000-00-00', 'В работе.', 26, '2025-07-09 10:57:28'),
(7, 20, 'Отказ ИК в открытом стволе, 30 м из 990м. Акселерометры работали', 'Вероятная причина в шине Enable, т.к. произошло обнуление фрейма.', '2026-01-19', NULL, '', 24, '2026-01-26 04:39:38'),
(8, 23, 'Отписал 9 часов и начал писать нули, затем работа восстановилась. Акселерометры писали весь интервал.', 'Найдены 2 проблемы в плате MCU. Питание +5В нестабильно скачет от 3,6 до 4,2В. Про прогреве платы феном до 60гр 3.3В падает до 2.5В. Обнаружил замыкание танталового конденсатора С5 22*16В.', '2026-03-17', '2026-03-19', 'Пропайка микросхемы DC-DC канала 5В, напряжение стало стабильным 4,78В. Замена танталового конденсатора С5. Прогрев платы до 90гр, всё нормально.', 24, '2026-03-19 09:05:57'),
(9, 22, 'Короткое замыкание по +-16В', 'КЗ в керамическом конденсаторе С7 1мкф на транзитной плате передатчика Т2.', '2026-02-16', '2026-02-17', 'Замена конденсатора. Тестовая запись. Потребление в норме.', 24, '2026-04-16 04:36:32');

